const PROTECTED_DATA = {"iv":"12Ty1Gz5aW2L5mnD","data":"","compression":"gzip"};

const SESSION_KEY = "nnmrcn_access_v1";
const encoder = new TextEncoder();
const decoder = new TextDecoder();

const menuButton = document.getElementById("menuButton");
const menuClose = document.getElementById("menuClose");
const menuPrincipale = document.getElementById("menuPrincipale");
const menuOverlay = document.getElementById("menuOverlay");

const loginForm = document.getElementById("loginForm");
const loginPassword = document.getElementById("loginPassword");
const loginButton = document.getElementById("loginButton");
const loginMessage = document.getElementById("loginMessage");
const loginLoggedOut = document.getElementById("loginLoggedOut");
const loginLoggedIn = document.getElementById("loginLoggedIn");
const loginLocation = document.getElementById("loginLocation");
const logoutButton = document.getElementById("logoutButton");

const poesiaOverlay = document.getElementById("poesiaOverlay");
const poesiaClose = document.getElementById("poesiaClose");
const poesiaDialogo = document.getElementById("poesiaDialogo");
const poesiaTesto = document.getElementById("poesiaTesto");

let sessioneCorrente = null;
let luoghiSbloccati = [];

function apriMenu() {
    menuPrincipale.classList.add("aperto");
    menuOverlay.classList.add("aperto");
    menuButton.setAttribute("aria-expanded", "true");
    document.body.classList.add("menu-aperto");
}

function chiudiMenu() {
    menuPrincipale.classList.remove("aperto");
    menuOverlay.classList.remove("aperto");
    menuButton.setAttribute("aria-expanded", "false");
    document.body.classList.remove("menu-aperto");
}

function apriPoesia(luogo) {
    poesiaDialogo.setAttribute("aria-label", `Poesia di ${luogo.nome}`);

    poesiaTesto.innerHTML = luogo.poesia || `
        <main class="poesia">
            <p>Poesia non ancora inserita.</p>
        </main>
    `;

    poesiaOverlay.hidden = false;
    poesiaOverlay.scrollTop = 0;
    document.body.classList.add("poesia-aperta");
    poesiaClose.focus();
}

function chiudiPoesia() {
    poesiaOverlay.hidden = true;
    document.body.classList.remove("poesia-aperta");
}

menuButton.addEventListener("click", apriMenu);
menuClose.addEventListener("click", chiudiMenu);
menuOverlay.addEventListener("click", chiudiMenu);
poesiaClose.addEventListener("click", chiudiPoesia);

document.addEventListener("keydown", function(event) {
    if (event.key === "Escape") {
        if (!poesiaOverlay.hidden) {
            chiudiPoesia();
        } else {
            chiudiMenu();
        }
    }
});

const map = L.map("map", {
    scrollWheelZoom: true
}).setView([45.5515, 12.3278], 13);

const satelliteUrl = "https://server.arcgisonline.com/ArcGIS/rest/services/World_Imagery/MapServer/tile/{z}/{y}/{x}";
const satelliteOptions = {
    maxZoom: 19,
    attribution: "Tiles &copy; Esri — Sources: Esri, Maxar, Earthstar Geographics, and the GIS User Community"
};

function creaSatellite() {
    return L.tileLayer(satelliteUrl, satelliteOptions);
}

const foto1975 = L.imageOverlay(
    "./marcon_1975_web.webp",
    [
        [45.5314854758, 12.2633666786],
        [45.5670779946, 12.3922261726]
    ],
    { opacity: 1 }
);

const oggi = L.layerGroup([creaSatellite()]);
const anno1975 = L.layerGroup([creaSatellite(), foto1975]);

oggi.addTo(map);

L.control.layers(
    {
        "Oggi": oggi,
        "1975": anno1975
    },
    null,
    { collapsed: false }
).addTo(map);

const locationsLayer = L.layerGroup().addTo(map);

function b64ToBytes(value) {
    const binary = atob(value);
    const bytes = new Uint8Array(binary.length);

    for (let i = 0; i < binary.length; i += 1) {
        bytes[i] = binary.charCodeAt(i);
    }

    return bytes;
}

function bytesToB64(bytes) {
    let binary = "";

    bytes.forEach(function(byte) {
        binary += String.fromCharCode(byte);
    });

    return btoa(binary);
}

function normalizzaPassword(value) {
    return value
        .trim()
        .toUpperCase()
        .replace(/[^A-Z0-9]/g, "");
}

async function trovaBundle(password) {
    const digest = new Uint8Array(
        await crypto.subtle.digest("SHA-256", encoder.encode(password))
    );

    const tag = bytesToB64(digest.slice(0, 10));
    return LOGIN_BUNDLES.find(function(bundle) {
        return bundle.t === tag;
    }) || null;
}

async function derivaChiave(password, salt) {
    const baseKey = await crypto.subtle.importKey(
        "raw",
        encoder.encode(password),
        "PBKDF2",
        false,
        ["deriveKey"]
    );

    return crypto.subtle.deriveKey(
        {
            name: "PBKDF2",
            salt,
            iterations: 200000,
            hash: "SHA-256"
        },
        baseKey,
        {
            name: "AES-GCM",
            length: 256
        },
        false,
        ["decrypt"]
    );
}

async function verificaPassword(passwordInserita) {
    const password = normalizzaPassword(passwordInserita);

    if (!password) {
        return null;
    }

    const bundle = await trovaBundle(password);

    if (!bundle) {
        return null;
    }

    try {
        const key = await derivaChiave(password, b64ToBytes(bundle.s));
        const plaintext = await crypto.subtle.decrypt(
            {
                name: "AES-GCM",
                iv: b64ToBytes(bundle.v)
            },
            key,
            b64ToBytes(bundle.d)
        );

        return JSON.parse(decoder.decode(plaintext));
    } catch (error) {
        return null;
    }
}

async function decomprimiGzip(bytes) {
    if (!("DecompressionStream" in window)) {
        throw new Error("Browser non compatibile con la decompressione richiesta.");
    }

    const stream = new Blob([bytes])
        .stream()
        .pipeThrough(new DecompressionStream("gzip"));

    return new Uint8Array(await new Response(stream).arrayBuffer());
}

async function decifraDati(masterKeyB64) {
    const key = await crypto.subtle.importKey(
        "raw",
        b64ToBytes(masterKeyB64),
        { name: "AES-GCM" },
        false,
        ["decrypt"]
    );

    const decrypted = new Uint8Array(
        await crypto.subtle.decrypt(
            {
                name: "AES-GCM",
                iv: b64ToBytes(PROTECTED_DATA.iv)
            },
            key,
            b64ToBytes(PROTECTED_DATA.data)
        )
    );

    const plainBytes = PROTECTED_DATA.compression === "gzip"
        ? await decomprimiGzip(decrypted)
        : decrypted;

    return JSON.parse(decoder.decode(plainBytes));
}

function salvaSessione(sessione) {
    sessionStorage.setItem(SESSION_KEY, JSON.stringify(sessione));
}

function leggiSessione() {
    try {
        const saved = sessionStorage.getItem(SESSION_KEY);
        return saved ? JSON.parse(saved) : null;
    } catch (error) {
        return null;
    }
}

function eliminaSessione() {
    sessionStorage.removeItem(SESSION_KEY);
}

function aggiornaInterfacciaAccesso(locationName) {
    if (locationName) {
        loginLoggedOut.hidden = true;
        loginLoggedIn.hidden = false;
        loginLocation.textContent = locationName;
        loginMessage.textContent = "";
    } else {
        loginLoggedOut.hidden = false;
        loginLoggedIn.hidden = true;
        loginLocation.textContent = "";
    }
}

function mostraLuoghi(luoghi, locationId) {
    locationsLayer.clearLayers();
    luoghiSbloccati = luoghi;

    luoghi.forEach(function(luogo) {
        const propria = luogo.id === locationId;

        const marker = L.circleMarker(
            [luogo.lat, luogo.lon],
            {
                radius: propria ? 8 : 6,
                color: "#171717",
                weight: propria ? 2 : 1.5,
                fillColor: propria ? "#171717" : "#f4f1e8",
                fillOpacity: 1
            }
        ).addTo(locationsLayer);

        marker.bindPopup(`
            <div class="popup-luogo">
                ${propria ? "<strong>La tua location</strong>" : ""}
                <button
                    type="button"
                    class="mostra-poesia"
                    data-location-id="${luogo.id}"
                >
                    Mostra poesia ${luogo.nome}
                </button>
            </div>
        `);
    });
}

async function attivaSessione(sessione, salva = true) {
    const protectedContent = await decifraDati(sessione.k);
    const propriaLocation = protectedContent.locations.find(function(luogo) {
        return luogo.id === sessione.i;
    });

    if (!propriaLocation) {
        throw new Error("Location non riconosciuta.");
    }

    sessioneCorrente = sessione;
    mostraLuoghi(protectedContent.locations, sessione.i);
    aggiornaInterfacciaAccesso(propriaLocation.nome);

    if (salva) {
        salvaSessione(sessione);
    }
}

async function eseguiLogin(password) {
    if (!(window.crypto && crypto.subtle)) {
        throw new Error("Questo browser non supporta l'accesso cifrato.");
    }

    const sessione = await verificaPassword(password);

    if (!sessione) {
        return false;
    }

    await attivaSessione(sessione, true);
    return true;
}

loginForm.addEventListener("submit", async function(event) {
    event.preventDefault();
    loginMessage.textContent = "";
    loginButton.disabled = true;
    loginButton.textContent = "Accesso...";

    try {
        const successo = await eseguiLogin(loginPassword.value);

        if (!successo) {
            loginMessage.textContent = "Password non valida.";
            return;
        }

        loginPassword.value = "";
    } catch (error) {
        loginMessage.textContent = "Non è stato possibile effettuare l'accesso su questo browser.";
    } finally {
        loginButton.disabled = false;
        loginButton.textContent = "Accedi";
    }
});

logoutButton.addEventListener("click", function() {
    sessioneCorrente = null;
    luoghiSbloccati = [];
    locationsLayer.clearLayers();
    eliminaSessione();
    aggiornaInterfacciaAccesso(null);
    loginMessage.textContent = "Accesso chiuso.";
});

map.on("popupopen", function(event) {
    const popup = event.popup.getElement();
    const pulsante = popup?.querySelector(".mostra-poesia");

    if (!pulsante) {
        return;
    }

    pulsante.addEventListener("click", function() {
        const luogo = luoghiSbloccati.find(function(item) {
            return item.id === pulsante.dataset.locationId;
        });

        if (!luogo) {
            return;
        }

        apriPoesia(luogo);
        map.closePopup();
    });
});

(async function ripristinaAccesso() {
    const saved = leggiSessione();

    if (!saved) {
        aggiornaInterfacciaAccesso(null);
        return;
    }

    try {
        await attivaSessione(saved, false);
    } catch (error) {
        eliminaSessione();
        aggiornaInterfacciaAccesso(null);
    }
})();
